      {view==="library"&&admin&&<div className="project-filters library-projects" aria-label="Project tài liệu">{projects.map(p=><button key={p.id} className={projectId===p.id?"active":""} onClick={()=>setProjectId(p.id)}>{p.name}</button>)}</div>}
      {view==="library"&&admin&&library?.projectId!==projectId&&<p className="subtle" role="status">Đang tải library của project…</p>}
